example.source:
deepml core 0.3
module corpus.deepml_core.example_06751
policy deterministic
policy no_network
module Encoder { fn run(x: f32[batch,5]) -> f32[batch,2] = relu(matmul(x, variable("enc"))) }
module Decoder { fn run(x: f32[batch,2]) -> f32[batch,5] = matmul(x, variable("dec")) }
graph Graph06751 train_infer {
  encoded = Encoder.run(input("sensor"))
  logic = embed deepml.logic version 0.3 { fn gate(x: Flag) -> Flag = x }
  scene_state = bind ja.portal.scene::SceneState(encoded)
  timeline_state = bind mcrt.portal.timeline::TimelineState(encoded)
  output = Decoder.run(encoded)
  loss = mse(output, target("sensor"))
}
checkpoint "pipeline_06751" every 11 steps
package model Graph06751 as "model_06751.msslb"

